@startuml

enum BuildingMaterial {
  wood
  brick
  concrete
}

abstract class Basement {
  + size : double
  + name : string
}

class EarthBasement extends Basement {
  + humidity : double
}

class ConcreteBasement extends Basement {}

class House {
  + address : string
  + buildingMaterial : BuildingMaterial
}

class SemiDetachedHouse extends House {
  + hasOwnGarden : boolean
  + windows : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticGarageDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : int
  + price : double
}

House "0..1" -- "0..1" Basement : has
SemiDetachedHouse "1" -- "2" Carport : has
SemiDetachedHouse "1" -- "0..1" Garage : has
House "1" -- "*" Company : is serviced by
Company "1" -- "*" JobLog : carries out
House "1" -- "*" JobLog : recorded in

@enduml

